/* ELKASS 5.4.3 — FINALNA NAPRAWA KATEGORII
   Ten plik celowo NIE używa starych danych z panelu ani ścieżek do zdjęć.
   Zdjęcia są wklejone w plik, więc kafelki działają nawet gdy hosting myli katalogi/cache.
*/
(function(){
  const IMAGES = {"RTV": "data:image/jpeg;base64,", "AGD": "data:image/jpeg;base64,", "AGD do zabudowy": "data:image/jpeg;base64,", "Małe AGD": "data:image/jpeg;base64,", "Komputery i telefony": "data:image/jpeg;base64,", "Serwis i doradztwo": "data:image/jpeg;base64,"};
  const CATS = [
    {name:'RTV', desc:'Telewizory, soundbary, kino domowe', subs:['Telewizory','Soundbary','Audio']},
    {name:'AGD', desc:'Lodówki, pralki, zmywarki', subs:['Lodówki','Pralki','Zmywarki']},
    {name:'AGD do zabudowy', desc:'Piekarniki, płyty, okapy', subs:['Piekarniki','Płyty','Okapy']},
    {name:'Małe AGD', desc:'Ekspresy, odkurzacze, żelazka', subs:['Ekspresy','Odkurzacze','Żelazka']},
    {name:'Komputery i telefony', desc:'Laptopy, smartfony, akcesoria', subs:['Laptopy','Smartfony','Akcesoria']},
    {name:'Serwis i doradztwo', desc:'Pomoc, konfiguracja, fachowe wsparcie', subs:['Wsparcie','Konfiguracja','Doradztwo']}
  ];
  function esc(s){return String(s||'').replace(/[&<>'"]/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[m]));}
  function url(cat, sub){ const p=new URLSearchParams(); p.set('category',cat); if(sub)p.set('subcategory',sub); return 'category.html?'+p.toString(); }
  function render(){
    const grid=document.getElementById('categories-grid');
    if(!grid) return;
    grid.className='elkass-final-category-grid';
    grid.innerHTML=CATS.map(c=>{
      const img=IMAGES[c.name];
      return `<article class="elkass-final-category-card">
        <img src="${img}" alt="${esc(c.name)}" class="elkass-final-category-img" loading="eager">
        <div class="elkass-final-category-shade"></div>
        <div class="elkass-final-category-content">
          <h3>${esc(c.name)}</h3>
          <p>${esc(c.desc)}</p>
          <div class="elkass-final-category-pills">${c.subs.map(s=>`<a href="${url(c.name,s)}">${esc(s)}</a>`).join('')}</div>
          <a class="elkass-final-category-button" href="${url(c.name)}">Zobacz więcej →</a>
        </div>
      </article>`;
    }).join('');
  }
  let locked=false;
  function safeRender(){ if(locked) return; locked=true; render(); locked=false; }
  if(document.readyState==='loading') document.addEventListener('DOMContentLoaded',safeRender); else safeRender();
  window.addEventListener('load',safeRender);
  [50,250,800,1600,3000].forEach(t=>setTimeout(safeRender,t));
  const obs=new MutationObserver(()=>{
    const grid=document.getElementById('categories-grid');
    if(grid && !grid.classList.contains('elkass-final-category-grid')) safeRender();
  });
  if(document.body) obs.observe(document.body,{childList:true,subtree:true,attributes:true,attributeFilter:['class']});
})();
